from taf.sw.dcap.rd.services.custom_traces.custom_base import CustomTraceBase
from taf.internal.sw.dcap.rd.client.dcap_lite.v3.models.trace_profile_tracer import TraceProfileTracer
from taf.internal.sw.dcap.rd.client.dcap_lite.v3.models.provided_trace import ProvidedTrace


class Custom5gTraceProfile(CustomTraceBase):
    def __init__(self, requirements, **kwargs):
        super(Custom5gTraceProfile, self).__init__()

        self.custom_trace_profile = self._generate_custom_trace_profile(requirements=requirements,
                                                                        trace_type="GNB",
                                                                        **kwargs)

    def get_l2_5g(self, included_trace_mode, **kwargs):
        provided_traces = []
        for l2_trace_mode in included_trace_mode:
            provided_traces.append(ProvidedTrace(
                snapshot=False,
                trace=l2_trace_mode,
                type="GNB"))
        params = [
            {
                "values": included_trace_mode,
                "name": "includedTraces"
            }
        ]
        if kwargs.get('kwargs', {}).get('l2ps_profile_list'):
            params.append({
                "values": kwargs['kwargs']['l2ps_profile_list'],
                "name": "l2PsProfileList"
            })

        return [TraceProfileTracer(
            provided_traces=provided_traces,
            params=params,
            type="GNB",
            name="UDP Tracer",
            id="l2Tracer")]

    @staticmethod
    def custom_5g_control_plane_interface(custom_5g_dict, **kwargs):
        gnb_custom_profile = "cp_5g"
        control_plane_interface = kwargs.get('control_plane_interface', 'auto')
        monitoring_profiles = kwargs.get('monitoring_profiles', '5g-full-call-scenarios')
        drb_monitoring_profiles = kwargs.get('drb_monitoring_profiles', None)
        drb_monitoring_tail_cutter = kwargs.get('drb_monitoring_tail_cutter', None)

        return TraceProfileTracer(
            provided_traces=[ProvidedTrace(
                snapshot=False,
                trace=custom_5g_dict[gnb_custom_profile].get('tracer_id'),
                type="GNB")],
            params=CustomTraceBase.custom_control_plane_interface(
                control_plane_interface=control_plane_interface,
                monitoring_profiles=monitoring_profiles,
                drb_monitoring_profiles=drb_monitoring_profiles,
                drb_monitoring_tail_cutter=drb_monitoring_tail_cutter),
            type="GNB",
            name=custom_5g_dict[gnb_custom_profile].get('name'),
            id=custom_5g_dict[gnb_custom_profile].get('tracer_id'))

    @staticmethod
    def custom_5g_bip_mirroring_interface(custom_5g_dict, **kwargs):
        gnb_custom_profile = 'bip_interface_mirroring'
        bip_mirroring_interface = kwargs.get('bip_mirroring_interface', 'L1-L2')
        bip_mirroring_time = kwargs.get('bip_mirroring_time', '60')
        return TraceProfileTracer(
            provided_traces=[ProvidedTrace(
                snapshot=False,
                trace=custom_5g_dict[gnb_custom_profile].get('tracer_id'),
                type="GNB")],
            params=[
                {
                    "name": "interface",
                    "values": [
                        bip_mirroring_interface
                    ]
                },
                {
                    "name": "mirroringTime",
                    "values": [
                        bip_mirroring_time
                    ]
                }
            ], type="GNB",
            name=custom_5g_dict[gnb_custom_profile].get('name'),
            id=custom_5g_dict[gnb_custom_profile].get('tracer_id'))

    @staticmethod
    def custom_5g_l1_stream(custom_5g_dict, **kwargs):
        gnb_custom_profile = 'L1stream'
        l1_trace = kwargs.get('l1_trace', ['ID 40: EM trace: L1-L2 interface'])
        return TraceProfileTracer(
            provided_traces=[ProvidedTrace(
                snapshot=False,
                trace=custom_5g_dict[gnb_custom_profile].get('tracer_id'),
                type="GNB")],
            params=[
                {
                    "name": "traceIds",
                    "values": l1_trace
                },
                {
                    "name": "subTypes",
                    "values": ['0' for _ in range(0, len(l1_trace))]
                },
                {
                    "name": "nbReports",
                    "values": ['0' for _ in range(0, len(l1_trace))]
                },
                {
                    "name": "dscp",
                    "values": [
                        "0"
                    ]
                },
                {
                    "name": "outputMode",
                    "values": [
                        "StreamingAndHistoryBuffer"
                    ]
                }
            ], type="GNB",
            name=custom_5g_dict[gnb_custom_profile].get('name'),
            id=custom_5g_dict[gnb_custom_profile].get('tracer_id'))

    @staticmethod
    def custom_5g_l1_IqTracer(custom_5g_dict, **kwargs):
        gnb_custom_profile = 'l1IqTracer'
        gnb_l1iq_direction = kwargs.get('gnb_l1iq_direction', 'UL')
        return TraceProfileTracer(
            provided_traces=[ProvidedTrace(
                snapshot=False,
                trace=custom_5g_dict[gnb_custom_profile].get('tracer_id'),
                type="GNB")],
            params=[
            {
              "name": "sfn",
              "values": [
                "65535"
              ]
            },
            {
              "name": "slot",
              "values": [
                "0"
              ]
            },
            {
              "name": "captureOnEvent",
              "values": [
                "false"
              ]
            },
            {
              "name": "capturePeriod",
              "values": [
                "1000"
              ]
            },
            {
              "name": "collectionCount",
              "values": [
                "0"
              ]
            },
            {
              "name": "subCellList",
              "values": []
            },
            {
              "name": "eitherDLorUL",
              "values": [
                gnb_l1iq_direction
              ]
            }
          ], type="GNB",
            name=custom_5g_dict[gnb_custom_profile].get('name'),
            id=custom_5g_dict[gnb_custom_profile].get('tracer_id'))


    def custom_tracers(self, custom_profile, trace_type, **kwargs):
        custom_5g_dict = {'cp_5g': {'name': 'Control Plane 5G', 'tracer_id': 'controlPlane5g'},
                          'controlPlane5g': {'name': 'Control Plane 5G', 'tracer_id': 'controlPlane5g'},
                          'pmFiles5g': {'tracer_id': 'pmFiles5g', 'name': 'PmFiles 5G'},
                          'l1IqTracer': {'tracer_id': 'l1IqTracer', 'name': 'L1-IQ 5G'},
                          'condor5gSyslog': {'tracer_id': 'condor5gSyslog', 'name': 'Condor 5G Syslog'},
                          'SCF5g': {'tracer_id': 'scf5g', 'name': 'SCF 5G'},
                          'bip_interface_mirroring': {'tracer_id': 'bip', 'name': 'BIP'},
                          'L1stream': {'tracer_id': 'l1StreamTracer5g', 'name': 'L1 Stream'},
                          'Tracer_5g': {'tracer_id': 'nTracer5g', 'name': 'Cell Trace'}}
        custom_gnb_profile_option = []

        profile_functions = {
            'cp_5g': self.custom_5g_control_plane_interface,
            'controlPlane5g': self.custom_5g_control_plane_interface,
            'bip_interface_mirroring': self.custom_5g_bip_mirroring_interface,
            'L1stream': self.custom_5g_l1_stream,
            'l1IqTracer': self.custom_5g_l1_IqTracer
        }

        if custom_profile in profile_functions:
            custom_gnb_profile_option.append(profile_functions[custom_profile](
                custom_5g_dict=custom_5g_dict,
                **kwargs))
        elif custom_profile in custom_5g_dict:
            custom_gnb_profile_option.append(TraceProfileTracer(
                provided_traces=[ProvidedTrace(
                    snapshot=False,
                    trace=custom_5g_dict[custom_profile].get('tracer_id'),
                    type=trace_type)],
                params=[], type=trace_type,
                name=custom_5g_dict[custom_profile].get('name'),
                id=custom_5g_dict[custom_profile].get('tracer_id')))
        return custom_gnb_profile_option
